'use client'

import { useState } from 'react'
import UserStats from './UserStats'

export default function Page() {
  const [users, setUsers] = useState([
    { id: 1, name: 'John', isActive: true },
    { id: 2, name: 'Jane', isActive: false },
    { id: 3, name: 'Bob', isActive: true },
  ])

  // Good example: derived value calculated directly
  const totalUsers = users.length

  return (
    <div>
      <h1>User Management</h1>
      <p>Total Users: {totalUsers}</p>

      <div>
        {users.map((user) => (
          <div key={user.id}>
            {user.name} - {user.isActive ? 'Active' : 'Inactive'}
          </div>
        ))}
      </div>

      <UserStats users={users} />
    </div>
  )
}

item.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { createServer } from 'vite'
import React from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import assert from 'node:assert/strict'

const server = await createServer({ server: { middlewareMode: true }, appType: 'custom', esbuild: { jsx: 'automatic' } })
try {
  const { default: UserStats } = await server.ssrLoadModule('/app/UserStats.tsx')
  const render = (users) => renderToStaticMarkup(React.createElement(UserStats, { users }))
  const mixed = render([{ id: 1, name: 'John', isActive: true }, { id: 2, name: 'Jane', isActive: false }, { id: 3, name: 'Bob', isActive: true }])
  assert.match(mixed, /Active Users: 2/)
  assert.match(mixed, /Inactive Users: 1/)
  assert.match(mixed, /Active Users Percentage: 67%/)
  const empty = render([])
  assert.match(empty, /Active Users: 0/)
  assert.match(empty, /Inactive Users: 0/)
  assert.match(empty, /Active Users Percentage: 0%/)
  const inactive = render([{ id: 1, name: 'John', isActive: false }])
  assert.match(inactive, /Active Users Percentage: 0%/)
  const active = render([{ id: 1, name: 'John', isActive: true }])
  assert.match(active, /Active Users Percentage: 100%/)
  console.log('UserStats rendering checks passed')
} finally {
  await server.close()
}
NODE"

